 const [value,setValue]=useState({...agent,runtimeDirectory:agent.runtimeDirectory??''}),[report,setReport]=useState<Diagnostic>(),[busy,setBusy]=useState(false),[connect,setConnect]=useState(''),[installTarget,setInstallTarget]=useState('claude'),[projectDir,setProjectDir]=useState(''),[previewText,setPreviewText]=useState('');
 const [capabilityHistory,setCapabilityHistory]=useState<any[]>([]),[capabilityData,setCapabilityData]=useState<{fingerprint:string;states:{capability:string;state:string;mode:string;testedAt:string|null;reason?:string|null}[];interceptionGaps?:{capability:string;reason:string;interceptable:boolean}[]}>(),[capabilityBusy,setCapabilityBusy]=useState(false);const update=(key:string,v:any)=>setValue(old=>({...old,[key]:v}));
